/**
 * CAT TOWN — the unlock graph (balance-and-meta.md §4).
 *
 * A small authored catalog plus an OPEN registry. Every entry is an addition
 * to the pool of possibilities — a cat who might come along, a stall that
 * might stock something, a drain that might be open — never a stat bump.
 *
 * The catalog is deliberately NOT a closed list: `registerUnlocks()` appends
 * defs at runtime, which is how Stands, items and events generated by the GM
 * or by other players become buyable here (§4 "the unlock IS the content
 * pool"). Every function in this layer takes an explicit `catalog` argument
 * (defaulting to the live registry) so the pure logic never depends on
 * module state.
 *
 * Pure: imports core/types only, no rng, no I/O.
 */
import type { PlaceDef, PlaceId, UnlockDef, UnlockId } from "./types.js";

/* ------------------------------------------------------------------ */
/* Places — the town as a map, not a list                             */
/* ------------------------------------------------------------------ */

