/** Unknown / pooled places fall back to the notice board. */
export const DEFAULT_PLACE: PlaceId = "board";

export function placeDef(id: PlaceId): PlaceDef {
  return (
    PLACES.find((p) => p.id === id) ??
    PLACES.find((p) => p.id === DEFAULT_PLACE)!
  );
}

