/* ------------------------------------------------------------------ */
/* Registry — additive, for pooled/generated content                  */
/* ------------------------------------------------------------------ */

const registry = new Map<UnlockId, UnlockDef>(
  BUILTIN_UNLOCKS.map((d) => [d.id, d]),
);

/**
 * Append (or replace) unlock defs — how a generated Stand/item/event becomes
 * purchasable in town. Later registrations of the same id win; the built-ins
 * come back with `resetUnlockRegistry()`.
 */
export function registerUnlocks(defs: readonly UnlockDef[]): void {
  for (const def of defs) registry.set(def.id, def);
}

/** Drop everything registered at runtime (tests, run teardown). */
export function resetUnlockRegistry(): void {
  registry.clear();
  for (const d of BUILTIN_UNLOCKS) registry.set(d.id, d);
}

/** The live catalog, built-ins first then registrations, in insertion order. */
export function unlockCatalog(): readonly UnlockDef[] {
  return [...registry.values()];
}

export function unlockDef(
  id: UnlockId,
  catalog: readonly UnlockDef[] = unlockCatalog(),
): UnlockDef | null {
  return catalog.find((d) => d.id === id) ?? null;
}

/** The defs sold at a place, in catalog order. */
export function unlocksAt(
  place: PlaceId,
  catalog: readonly UnlockDef[] = unlockCatalog(),
): UnlockDef[] {
  const known = new Set(PLACES.map((p) => p.id));
  return catalog.filter((d) =>
    known.has(d.place) ? d.place === place : place === DEFAULT_PLACE,
  );
}

/** Σ of every price in the catalog — the town's total ask. */
export function catalogCost(
  catalog: readonly UnlockDef[] = unlockCatalog(),
): number {
  return catalog.reduce((s, d) => s + d.cost, 0);
}
